//! Port candidate parsing with `std::stoi`-like semantics.

/// Parse a port candidate the way C++ `std::stoi` (base 10) would:
/// skip leading whitespace, accept an optional sign, then consume
/// decimal digits until the first non-digit. Returns `None` when no
/// digits are present or the value does not fit in a C++ `int`.
pub fn parse_stoi(s: &str) -> Option<i64> {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    if i == start {
        return None;
    }
    let value = if negative { -value } else { value };
    // std::stoi throws std::out_of_range when the value exceeds int.
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return None;
    }
    Some(value)
}
