//! Entry point mirroring `test7.cpp`.
//!
//! Reads a URL from the first command-line argument, parses it with the
//! `url_parser` library module, and prints each component on its own line.

#[path = "src/url_parser.rs"]
mod url_parser;

use url_parser::URL;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let url = &args[1];
    let parser = URL::new(url);

    println!("{}", parser.scheme());
    println!("{}", parser.authority());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());
    println!("{}", parser.is_valid() as i32);
}

//! A minimal URL parser re-implementing the behavior of the C++
//! `url_parser::URL` class (black-box compatible).

mod port;

/// A parsed URL, exposing the same accessors as the C++ `url_parser::URL`.
pub struct URL {
    scheme: String,
    authority: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl URL {
    /// Parse `url` into its components.
    pub fn new(url: &str) -> URL {
        let mut scheme = String::new();
        let mut authority = String::new();
        let mut path = String::new();
        let mut query = String::new();
        let mut fragment = String::new();
        let mut port_num: i32 = -1;

        // Scheme: everything before "://", lower-cased, if present.
        let mut rest = url;
        let has_authority = match url.find("://") {
            Some(pos) => {
                scheme = url[..pos].to_ascii_lowercase();
                rest = &url[pos + 3..];
                true
            }
            None => false,
        };

        // Fragment: everything after the first '#'.
        if let Some(pos) = rest.find('#') {
            fragment = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        // Query: everything after the first '?'.
        if let Some(pos) = rest.find('?') {
            query = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        // The authority/path split only happens when "://" was present.
        if has_authority {
            match rest.find('/') {
                Some(pos) => {
                    authority = rest[..pos].to_string();
                    path = rest[pos..].to_string();
                }
                None => {
                    authority = rest.to_string();
                }
            }

            // Port: first ':' after the last '@' in the authority. The
            // authority is rebuilt from the host part plus the normalized
            // port; an invalid port is dropped entirely.
            let start = authority.rfind('@').map(|i| i + 1).unwrap_or(0);
            if let Some(rel) = authority[start..].find(':') {
                let colon = start + rel;
                let candidate = &authority[colon + 1..];
                let host = authority[..colon].to_string();
                authority = match port::parse_stoi(candidate) {
                    Some(p) if (0..=65535).contains(&p) => {
                        port_num = p as i32;
                        format!("{}:{}", host, p)
                    }
                    _ => host,
                };
            }
        } else {
            path = rest.to_string();
        }

        let valid = !authority.is_empty() || !path.is_empty();

        URL {
            scheme,
            authority,
            port: port_num,
            path,
            query,
            fragment,
            valid,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

//! Port candidate parsing with `std::stoi`-like semantics (base 10).

/// Parse a port candidate the way C++ `std::stoi` would: skip leading
/// whitespace, accept an optional sign, then consume decimal digits until
/// the first non-digit character. Returns `None` when no digits are present
/// (`std::invalid_argument`) or the value does not fit in a C++ `int`
/// (`std::out_of_range`).
pub fn parse_stoi(s: &str) -> Option<i64> {
    let bytes = s.as_bytes();
    let mut i = 0;

    // C locale isspace(): space, \t, \n, \v, \f, \r.
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let digits_start = i;
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    if i == digits_start {
        return None;
    }

    let value = if negative { -value } else { value };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return None;
    }
    Some(value)
}

